{"contents":"import { useState } from 'react';
import { cn } from '@/lib/utils';

interface HoverTooltipProps {
  content: string;
  enabled?: boolean;
  children: React.ReactNode;
  className?: string;
  tooltipClassName?: string;
  side?: 'top' | 'bottom';
}

export function HoverTooltip({
  content,
  enabled = true,
  children,
  className,
  tooltipClassName,
  side = 'top',
}: HoverTooltipProps) {
  const [open, setOpen] = useState(false);
  const handleFocusCapture = (event: React.FocusEvent<HTMLSpanElement>) => {
    // Drawer 打开时会触发程序化 focus，避免这类 focus 直接展示 tooltip
    if (event.target instanceof HTMLElement && event.target.matches(':focus-visible')) {
      setOpen(true);
    }
  };

  if (!enabled) {
    return <span className={cn('inline-flex', className)}>{children}</span>;
  }

  return (
    <span
      className={cn('relative inline-flex', className)}
      onMouseEnter={() => setOpen(true)}
      onMouseLeave={() => setOpen(false)}
      onFocusCapture={handleFocusCapture}
      onBlurCapture={() => setOpen(false)}
    >
      {children}
      {open ? (
        <span
          role="tooltip"
          className={cn(
            'pointer-events-none absolute left-1/2 -translate-x-1/2 whitespace-nowrap rounded-md bg-black px-2 py-1 text-xs text-white shadow-sm',
            side === 'top' ? 'bottom-full mb-2' : 'top-full mt-2',
            tooltipClassName,
          )}
        >
          {content}
        </span>
      ) : null}
    </span>
  );
}
