import { useCallback, useState } from 'react';
import type { RefObject } from 'react';
import { useQuoteHighlightJump } from './useQuoteHighlightJump';
import { useSelectionTip } from './useSelectionTip';
import type { QuotedDraft } from './types';

type UseQuoteSelectionOptions = {
  isBusy: boolean;
  hasMessages: boolean;
  scrollAreaRef: RefObject<HTMLDivElement | null>;
  inputRef: RefObject<HTMLTextAreaElement | null>;
  getScrollElement: () => HTMLElement | null;
};

const EMPTY_QUOTED_DRAFT: QuotedDraft = {
  content: '',
  sourceMessageId: '',
  sourceStart: null,
  sourceEnd: null,
};

export function useQuoteSelection({
  isBusy,
  hasMessages,
  scrollAreaRef,
  inputRef,
  getScrollElement,
}: UseQuoteSelectionOptions) {
  const [quotedDraft, setQuotedDraft] = useState<QuotedDraft>(EMPTY_QUOTED_DRAFT);

  const { selectionTip, consumeSelectionTip, clearSelectionTip } = useSelectionTip({
    isBusy,
    hasMessages,
    inputRef,
  });

  const { jumpToQuotedSource } = useQuoteHighlightJump({
    scrollAreaRef,
    getScrollElement,
  });

  const applySelectionQuote = useCallback(() => {
    const nextDraft = consumeSelectionTip();
    if (!nextDraft) return;
    setQuotedDraft(nextDraft);
  }, [consumeSelectionTip]);

  const clearQuoteDraft = useCallback(() => {
    setQuotedDraft(EMPTY_QUOTED_DRAFT);
  }, []);

  const resetQuoteDraftAndSelection = useCallback(() => {
    setQuotedDraft(EMPTY_QUOTED_DRAFT);
    clearSelectionTip();
  }, [clearSelectionTip]);

  return {
    selectionTip,
    quotedDraft,
    applySelectionQuote,
    clearQuoteDraft,
    clearSelectionTip,
    resetQuoteDraftAndSelection,
    jumpToQuotedSource,
  };
}
