import { useCallback, useEffect, useRef, useState } from 'react';
import type { RefObject } from 'react';
import type { QuotedDraft, SelectionTipState } from './types';

type UseSelectionTipOptions = {
  isBusy: boolean;
  hasMessages: boolean;
  inputRef: RefObject<HTMLTextAreaElement | null>;
};

export function useSelectionTip({ isBusy, hasMessages, inputRef }: UseSelectionTipOptions) {
  const [selectionTip, setSelectionTip] = useState<SelectionTipState | null>(null);
  const isBusyRef = useRef(isBusy);
  const hasMessagesRef = useRef(hasMessages);
  const rafIdRef = useRef<number | null>(null);

  useEffect(() => {
    isBusyRef.current = isBusy;
    hasMessagesRef.current = hasMessages;
    if (!hasMessages) {
      setSelectionTip(null);
    }
  }, [hasMessages, isBusy]);

  const clearBrowserSelection = useCallback(() => {
    window.getSelection()?.removeAllRanges();
  }, []);

  const updateSelectionTip = useCallback(() => {
    if (isBusyRef.current || !hasMessagesRef.current) {
      setSelectionTip(null);
      return;
    }

    const selection = window.getSelection();
    if (!selection || selection.rangeCount === 0 || selection.isCollapsed) {
      setSelectionTip(null);
      return;
    }

    const text = selection.toString().trim();
    if (!text) {
      setSelectionTip(null);
      return;
    }

    const range = selection.getRangeAt(0);
    const ancestor = range.commonAncestorContainer;
    const element =
      ancestor.nodeType === Node.TEXT_NODE ? ancestor.parentElement : (ancestor as Element | null);

    const inAssistantMessage = element?.closest('[data-chat-message-type="assistant"]');
    if (!inAssistantMessage) {
      setSelectionTip(null);
      return;
    }
    const sourceMessageId = inAssistantMessage.getAttribute('data-chat-message-id') ?? undefined;
    const sourceElement = inAssistantMessage as HTMLElement;

    const calculateAbsoluteOffset = (targetNode: Node, nodeOffset: number): number | null => {
      const walker = document.createTreeWalker(sourceElement, NodeFilter.SHOW_TEXT);
      let current = walker.nextNode();
      let total = 0;
      while (current) {
        const textNode = current as Text;
        const valueLength = textNode.nodeValue?.length ?? 0;
        if (current === targetNode) {
          return total + Math.max(0, Math.min(nodeOffset, valueLength));
        }
        total += valueLength;
        current = walker.nextNode();
      }
      return null;
    };

    const sourceStart = calculateAbsoluteOffset(range.startContainer, range.startOffset);
    const sourceEnd = calculateAbsoluteOffset(range.endContainer, range.endOffset);

    const rect = range.getBoundingClientRect();
    if (rect.width === 0 && rect.height === 0) {
      setSelectionTip(null);
      return;
    }

    const viewportPadding = 12;
    const tipHalfWidth = Math.min(112, Math.max(72, Math.round(window.innerWidth * 0.16)));
    const nextLeft = Math.min(
      Math.max(rect.left + rect.width / 2, tipHalfWidth + viewportPadding),
      window.innerWidth - tipHalfWidth - viewportPadding,
    );
    const nextTop = Math.max(12, rect.top - 10);

    setSelectionTip({
      text,
      sourceMessageId,
      sourceStart: sourceStart ?? undefined,
      sourceEnd: sourceEnd ?? undefined,
      top: nextTop,
      left: nextLeft,
    });
  }, []);

  const consumeSelectionTip = useCallback((): QuotedDraft | null => {
    if (!selectionTip?.text) return null;

    const nextDraft: QuotedDraft = {
      content: selectionTip.text,
      sourceMessageId: selectionTip.sourceMessageId ?? '',
      sourceStart: selectionTip.sourceStart ?? null,
      sourceEnd: selectionTip.sourceEnd ?? null,
    };

    setSelectionTip(null);
    clearBrowserSelection();
    inputRef.current?.focus();
    return nextDraft;
  }, [clearBrowserSelection, inputRef, selectionTip]);

  const clearSelectionTip = useCallback(() => {
    setSelectionTip(null);
  }, []);

  useEffect(() => {
    const scheduleUpdate = () => {
      if (rafIdRef.current !== null) return;
      rafIdRef.current = window.requestAnimationFrame(() => {
        rafIdRef.current = null;
        updateSelectionTip();
      });
    };

    const handleSelectionChange = () => {
      scheduleUpdate();
    };

    const handleMouseUp = () => {
      scheduleUpdate();
    };

    const handleKeyUp = () => {
      scheduleUpdate();
    };

    const handleScroll = () => {
      setSelectionTip(null);
    };

    document.addEventListener('selectionchange', handleSelectionChange);
    document.addEventListener('mouseup', handleMouseUp);
    document.addEventListener('keyup', handleKeyUp);
    window.addEventListener('scroll', handleScroll, true);

    return () => {
      if (rafIdRef.current !== null) {
        window.cancelAnimationFrame(rafIdRef.current);
        rafIdRef.current = null;
      }
      document.removeEventListener('selectionchange', handleSelectionChange);
      document.removeEventListener('mouseup', handleMouseUp);
      document.removeEventListener('keyup', handleKeyUp);
      window.removeEventListener('scroll', handleScroll, true);
    };
  }, [updateSelectionTip]);

  return {
    selectionTip,
    consumeSelectionTip,
    clearSelectionTip,
  };
}
