{"contents":"import type { UserMessageInput } from '@/types/agent';

import type { NormalizedUserMessageInput } from './createSendMessageOrchestrator';

export function normalizeUserMessageInput(input: UserMessageInput): NormalizedUserMessageInput {
  if (typeof input === 'string') {
    const question = input.trim();
    return { question, prompt: question };
  }

  const question = input.question.trim();
  const quotedContent = input.quotedContent?.trim();
  const quotedSourceMessageId =
    typeof input.quotedSourceMessageId === 'string' && input.quotedSourceMessageId.trim()
      ? input.quotedSourceMessageId.trim()
      : undefined;
  const quotedSourceStart =
    typeof input.quotedSourceStart === 'number' && Number.isFinite(input.quotedSourceStart)
      ? input.quotedSourceStart
      : undefined;
  const quotedSourceEnd =
    typeof input.quotedSourceEnd === 'number' && Number.isFinite(input.quotedSourceEnd)
      ? input.quotedSourceEnd
      : undefined;

  if (!quotedContent) {
    return {
      question,
      quotedSourceMessageId,
      quotedSourceStart,
      quotedSourceEnd,
      prompt: question,
    };
  }

  return {
    question,
    quotedContent,
    quotedSourceMessageId,
    quotedSourceStart,
    quotedSourceEnd,
    prompt: `【引用内容】\n${quotedContent}\n\n【用户问题】\n${question}`,
  };
}
