{"contents":"import type { AgentReference, AgentReferenceMap } from '@/types/agent';

function normalizeRefToken(value?: string) {
  if (!value) return undefined;
  const trimmed = value.trim();
  if (!trimmed) return undefined;
  return trimmed.toLowerCase().replace(/^ref-/, '');
}

export function buildReferenceAliases(reference: AgentReference): AgentReferenceMap {
  const aliases: AgentReferenceMap = {};
  aliases[reference.refId] = reference;
  aliases[reference.refId.toLowerCase()] = reference;

  if (!reference.refId.toLowerCase().startsWith('ref-')) {
    aliases[`ref-${reference.refId}`] = reference;
    aliases[`ref-${reference.refId}`.toLowerCase()] = reference;
  }

  if (reference.toolUseId) {
    aliases[reference.toolUseId] = reference;
    aliases[reference.toolUseId.toLowerCase()] = reference;
    aliases[`ref-${reference.toolUseId}`] = reference;
    aliases[`ref-${reference.toolUseId}`.toLowerCase()] = reference;
  }

  if (reference.dataSourceId) {
    aliases[reference.dataSourceId] = reference;
    aliases[reference.dataSourceId.toLowerCase()] = reference;
    aliases[`ref-${reference.dataSourceId}`] = reference;
    aliases[`ref-${reference.dataSourceId}`.toLowerCase()] = reference;
  }

  return aliases;
}

export function findExistingReference(
  reference: AgentReference,
  refs?: AgentReferenceMap,
): AgentReference | undefined {
  if (!refs) return undefined;

  const targetRefToken = normalizeRefToken(reference.refId);
  const targetToolUseId = reference.toolUseId?.toLowerCase();
  const targetDataSourceId = reference.dataSourceId?.toLowerCase();

  let bestMatch: AgentReference | undefined;
  Object.values(refs).forEach((item) => {
    if (!item) return;

    const refToken = normalizeRefToken(item.refId);
    const matchesRef = targetRefToken && refToken === targetRefToken;
    const matchesToolUse = targetToolUseId && item.toolUseId?.toLowerCase() === targetToolUseId;
    const matchesDataSource =
      targetDataSourceId && item.dataSourceId?.toLowerCase() === targetDataSourceId;

    if (!matchesRef && !matchesToolUse && !matchesDataSource) return;

    if (!bestMatch) {
      bestMatch = item;
      return;
    }

    if (!bestMatch.data && item.data) {
      bestMatch = item;
      return;
    }

    if (!bestMatch.input && item.input) {
      bestMatch = item;
    }
  });

  return bestMatch;
}

export function mergeReference(
  existing: AgentReference | undefined,
  incoming: AgentReference,
): AgentReference {
  if (!existing) return incoming;

  return {
    ...existing,
    ...incoming,
    refId: incoming.refId || existing.refId,
    toolName: incoming.toolName ?? existing.toolName,
    toolUseId: incoming.toolUseId ?? existing.toolUseId,
    dataSourceId: incoming.dataSourceId ?? existing.dataSourceId,
    preview: incoming.preview ?? existing.preview,
    input: incoming.input ?? existing.input,
    inputPreview: incoming.inputPreview ?? existing.inputPreview,
    data: incoming.data ?? existing.data,
    rawToolCall: incoming.rawToolCall ?? existing.rawToolCall,
    rawToolResult: incoming.rawToolResult ?? existing.rawToolResult,
  };
}
