{"contents":"import type { AgentTodoList, ChatMessage } from '@/types/agent';

type InitializeSendMessageTurnOptions<TTurnRuntime> = {
  conversationId: number;
  question: string;
  quotedContent?: string;
  quotedSourceMessageId?: string;
  quotedSourceStart?: number;
  quotedSourceEnd?: number;
  sessionId?: string;
  streamService: {
    create: (conversationId: number) => { streamId: string; controller: AbortController };
  };
  runtimeStore: {
    clearFinalMessageId: (conversationId: number) => void;
    clearWidgetMessageIds: (conversationId: number) => void;
  };
  createId: () => string;
  pushMessage: (conversationId: number, message: ChatMessage) => void;
  updateLoadingCounter: (conversationId: number, delta: 1 | -1) => void;
  updateFollowupsForConversation: (conversationId: number, nextFollowups: string[]) => void;
  clearAssistantStreamIds: (conversationId: number) => void;
  updateTodoListForConversation: (
    conversationId: number,
    updater: (prev: AgentTodoList | null) => AgentTodoList | null,
  ) => void;
  createTurnRuntime: (options: {
    initialSessionId: string;
    userMessage: ChatMessage;
    timestamp: Date;
    controller: AbortController;
  }) => TTurnRuntime;
};

type InitializeSendMessageTurnResult<TTurnRuntime> = {
  streamId: string;
  controller: AbortController;
  initialSessionId: string;
  turnRuntime: TTurnRuntime;
};

export function initializeSendMessageTurn<TTurnRuntime>(
  options: InitializeSendMessageTurnOptions<TTurnRuntime>,
): InitializeSendMessageTurnResult<TTurnRuntime> {
  const {
    conversationId,
    question,
    quotedContent,
    quotedSourceMessageId,
    quotedSourceStart,
    quotedSourceEnd,
    sessionId,
    streamService,
    runtimeStore,
    createId,
    pushMessage,
    updateLoadingCounter,
    updateFollowupsForConversation,
    clearAssistantStreamIds,
    updateTodoListForConversation,
    createTurnRuntime,
  } = options;

  const timestamp = new Date();
  const { streamId, controller } = streamService.create(conversationId);

  updateLoadingCounter(conversationId, 1);
  updateFollowupsForConversation(conversationId, []);
  runtimeStore.clearFinalMessageId(conversationId);
  runtimeStore.clearWidgetMessageIds(conversationId);
  clearAssistantStreamIds(conversationId);

  const userMessage: ChatMessage = {
    id: createId(),
    conversationId,
    type: 'user',
    content: question,
    quotedContent,
    quotedSourceMessageId,
    quotedSourceStart,
    quotedSourceEnd,
    timestamp,
  };
  pushMessage(conversationId, userMessage);

  const initialSessionId = sessionId || Date.now().toString();
  if (sessionId) {
    updateTodoListForConversation(conversationId, () => null);
  }

  const turnRuntime = createTurnRuntime({
    initialSessionId,
    userMessage,
    timestamp,
    controller,
  });

  return {
    streamId,
    controller,
    initialSessionId,
    turnRuntime,
  };
}
